type MyReturnType<T> = T extends (...args: never[]) => infer R ? R : never;
type MyParameters<T> = T extends (...args: infer P) => unknown ? P : never;

async function loadUser(id: string): Promise<{ id: string }> {
  const res = await fetch(`/api/users/${id}`);
  return res.json();
}

type UserPromise = MyReturnType<typeof loadUser>;
// Promise<{ id: string }>

type LoadArgs = MyParameters<typeof loadUser>;
// [id: string]

type MyAwaited<T> = T extends null | undefined
  ? T
  : T extends object & { then(onfulfilled: infer F): unknown }
    ? F extends (value: infer V) => unknown
      ? MyAwaited<V>
      : never
    : T;

type Deep = MyAwaited<Promise<Promise<string>>>;
// string

type EventMap = {
  login: { userId: string };
  logout: { reason: string };
};

type HandlerFor<K extends keyof EventMap> = (payload: EventMap[K]) => void;

type Handlers = {
  [K in keyof EventMap]: HandlerFor<K>;
};

// infer from callback union
type EventName<T> = T extends (payload: infer P extends EventMap[keyof EventMap])
  ? keyof { [K in keyof EventMap]: EventMap[K] extends P ? K : never }
  : never;

// Error: infer only allowed in extends clause of conditional type
type Bad<T> = infer U;

// Fix:
type Good<T> = T extends Array<infer U> ? U : never;
